const $=id=>document.getElementById(id);let model;
fetch('model.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(m=>{model=m;$('check').disabled=false;$('check').textContent='Check message  →'}).catch(()=>{$('check').textContent='Model unavailable';$('error').textContent='Could not load the model. Please refresh to try again.'});
const reset=()=>{$('result').hidden=true;$('empty').hidden=false;$('error').textContent='';$('count').textContent=`${$('message').value.length.toLocaleString()} / 20,000`};
$('message').addEventListener('input',reset);
$('clear').onclick=()=>{$('message').value='';reset();$('message').focus()};
const samples={spam:'URGENT! You have won a FREE cash prize of £1000. Call now to claim your reward!',ham:'Hi, are we still meeting for lunch tomorrow? Let me know what time works for you.'};
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('message').value=samples[b.dataset.example];reset();$('message').focus()});
$('form').onsubmit=e=>{e.preventDefault();if(!model)return;const text=$('message').value.trim();if(!text){$('error').textContent='Please enter a message first.';$('message').focus();return}const r=classify(text,model);$('empty').hidden=true;$('result').hidden=false;$('error').textContent='';const color=r.label?'#b75c35':'#146b57';$('verdict').textContent=r.matched?(r.label?'Spam detected':'Not spam'):'Unable to assess';$('verdict').style.color=r.matched?color:'#7b7252';$('result-icon').textContent=r.matched?(r.label?'⚑':'✓'):'?';$('result-icon').style.color=color;$('explanation').textContent=r.matched?(r.label?'This message resembles spam in your training data. Treat unexpected offers and requests with caution.':'This message resembles normal messages in your training data. Still check who sent it before opening links.'):'No words matched the trained vocabulary. Try a longer English message.';$('score').textContent=r.matched?(r.probability*100).toFixed(1)+'%':'N/A';$('bar').style.width=r.matched?(r.probability*100)+'%':'0';$('bar').style.background=color;$('coverage').textContent=r.matched?`${r.matched} unique words matched the model vocabulary. Prediction uses the full TF-IDF model.`:'No reliable prediction is available for this input.'};
